import React, { forwardRef, useLayoutEffect, useRef } from 'react';
import { DateRange, Matcher } from 'react-day-picker';
import { X } from '@hexa-ui/icons';
import { Input } from '../../../input';
import { Calendar, CalendarRef } from '../../../calendar';
import { formatedDate } from '../../../input/DatePickerInput/utils';
import { Row } from '../DatePickerBase/DatePickerBase.styles';
import { DatePickerMobileBaseProps } from '../DatePickerBase/DatePickerBase.types';
import { IconButton } from '../../../icon-button';
import { MobileContainer, MobileContent } from './DatePickerMobile.styles';

export const DatePickerMobile = forwardRef(
  (
    { onChange, onClose, mode = 'single', value, ...rest }: DatePickerMobileBaseProps,
    forwardedRef: React.ForwardedRef<HTMLDivElement>
  ): JSX.Element => {
    const calendarRef = useRef<CalendarRef>(null);

    useLayoutEffect(() => {
      if (!value) return;
      if (mode === 'range') {
        calendarRef.current?.changeSelection({ from: value[0], to: value[1] });
      } else {
        calendarRef.current?.changeSelection(value);
      }
    }, [value, mode]);

    const handleSelect = (selection: Matcher | Matcher[] | undefined) => {
      if (selection === undefined) {
        onChange();
      } else if (selection instanceof Date) {
        onChange([selection] as Date[]);
      } else {
        const range = selection as DateRange;
        onChange([range.from, range.to] as Date[]);
      }
    };

    return (
      <MobileContainer border="large" elevated="medium" ref={forwardedRef}>
        <MobileContent>
          {mode === 'single' && (
            <Row css={{ gap: '$4', marginBottom: '$6' }}>
              <Input
                type="text"
                width="100%"
                readOnly
                value={formatedDate(value?.[0]?.toString() ?? '', {
                  month: 'short',
                  day: '2-digit',
                  year: 'numeric',
                })}
              />
              <IconButton
                icon={X}
                variant="tertiary"
                size="small"
                onClick={onClose}
                data-testid="icon-button-close-x"
              />
            </Row>
          )}
          {mode === 'range' && (
            <>
              <IconButton
                icon={X}
                variant="tertiary"
                size="small"
                onClick={onClose}
                style={{ marginLeft: 'auto' }}
                data-testid="icon-button-close-x"
              />
              <Row css={{ gap: '$2', justifyContent: 'flex-end', margin: '$4 0 $6 0' }}>
                <Input
                  type="text"
                  width="9.5rem"
                  readOnly
                  value={formatedDate(value?.[0]?.toString() ?? '')}
                />
                <Input
                  type="text"
                  width="9.5rem"
                  readOnly
                  value={formatedDate(value?.[1]?.toString() ?? '')}
                />
              </Row>
            </>
          )}
          <Calendar
            onChange={handleSelect}
            mode={mode}
            ref={calendarRef}
            defaultMonth={value?.[0]}
            {...rest}
            numberOfMonths={1}
          />
        </MobileContent>
      </MobileContainer>
    );
  }
);
